 if(!["invitee.created","invitee.canceled"].includes(event.event)||!invitee)return publicJson(res,200,{received:true,tracked:false});
 if(!process.env.SUPABASE_URL||!process.env.SUPABASE_SERVICE_ROLE_KEY)return publicJson(res,503,{error:"Booking event storage is not configured."});
 const admin=createClient(process.env.SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});
 if(event.event==="invitee.canceled"&&(!utmClientId||!uuidPattern.test(utmClientId))){const {error}=await admin.from("booking_events").update({status:"canceled",updated_at:new Date().toISOString()}).eq("invitee_uri",invitee);if(error)return publicJson(res,500,{error:"Could not update booking cancellation."});return publicJson(res,200,{received:true,tracked:true})}
 if(!utmClientId||!uuidPattern.test(utmClientId))return publicJson(res,200,{received:true,tracked:false});
