const json = (res, status, data) => { res.writeHead(status, headers); res.end(JSON.stringify(data)); };
const getClient = (token) => createClient(process.env.SUPABASE_URL, process.env.SUPABASE_ANON_KEY, { global: { headers: token ? { Authorization: `Bearer ${token}` } : {} }, auth: { persistSession: false } });
const tokenKey = () => { const key=Buffer.from(process.env.INSTAGRAM_TOKEN_ENCRYPTION_KEY||"","base64");if(key.length!==32)throw Error("Instagram token encryption key must be 32-byte base64.");return key; };
