   if (!connection || connection.status !== "connected") return json(res, 404, { error: "Instagram is not connected." });
   if (!connection.token_expires_at || new Date(connection.token_expires_at) <= new Date()) return json(res, 409, { error: "This token has expired. Reconnect Instagram." });
