 "POST /video-version-token": async(req,res,ctx)=>{if(ctx.profile.role!=="admin")return json(res,403,{error:"Admin access required."});const b=await body(req);const {data:v,error:ve}=await ctx.supa.from("video_projects").select("id,client_id").eq("id",b.video_id).single();if(ve||!v)return json(res,404,{error:"Video not found."});if(!process.env.SUPABASE_SERVICE_ROLE_KEY)return json(res,503,{error:"Secure storage requires server storage configuration."});const {data:vs}=await ctx.supa.from("video_versions").select("version_number").eq("video_id",v.id).order("version_number",{ascending:false}).limit(1);const path=`${v.client_id}/${v.id}/version-${(vs?.[0]?.version_number||0)+1}-${crypto.randomUUID()}.mp4`;const admin=createClient(process.env.SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});const {data,error}=await admin.storage.from("client-videos").createSignedUploadUrl(path);return error?json(res,400,{error:"Could not prepare secure upload."}):json(res,200,{path,token:data.token,url:data.signedUrl})},
 "POST /videos": async(req,res,ctx)=>{if(ctx.profile.role!=="client")return json(res,403,{error:"Client access required."});const b=await body(req);if(!b.title||!b.storage_path||!b.storage_path.startsWith(`${ctx.profile.client_id}/`))return json(res,400,{error:"Title and a valid uploaded file are required."});const {data,error}=await ctx.supa.from("video_projects").insert({client_id:ctx.profile.client_id,title:b.title,description:b.description,recording_notes:b.recording_notes,reference_id:b.reference_id||null,raw_storage_path:b.storage_path,status:"Uploaded",created_by:ctx.user.id}).select().single();return error?json(res,400,{error:"Could not save video submission."}):json(res,201,{data})},
 "POST /upload-token": async(req,res,ctx)=>{if(ctx.profile.role!=="client")return json(res,403,{error:"Client access required."});const b=await body(req);const size=Number(b.size),max=Number(process.env.MAX_VIDEO_SIZE_MB||500)*1024*1024;if(!Number.isFinite(size)||size<=0||size>max||!(["video/mp4","video/quicktime"].includes(b.type)))return json(res,400,{error:"Unsupported video type or file size."});if(!process.env.SUPABASE_SERVICE_ROLE_KEY)return json(res,503,{error:"Secure storage requires the server storage configuration."});const safe=String(b.filename||"video").replace(/[^a-zA-Z0-9._-]/g,"_").slice(-100);const path=`${ctx.profile.client_id}/${crypto.randomUUID()}-${safe}`;const admin=createClient(process.env.SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});const {data,error}=await admin.storage.from("client-videos").createSignedUploadUrl(path);return error?json(res,400,{error:"Could not prepare secure upload."}):json(res,200,{path,token:data.token,url:data.signedUrl})},
 "POST /video-status": async(req,res,ctx)=>{if(ctx.profile.role!=="admin")return json(res,403,{error:"Admin access required."});const b=await body(req);const allowed=["Uploaded","Queued for Editing","Editing","Ready for Review","Changes Requested","Approved","Ready to Publish","Published"];if(!allowed.includes(b.status))return json(res,400,{error:"Invalid video status."});const {data,error}=await ctx.supa.from("video_projects").update({status:b.status,updated_at:new Date().toISOString()}).eq("id",b.video_id).select().single();if(error)return json(res,400,{error:"Could not update status."});await ctx.supa.from("video_status_history").insert({video_id:b.video_id,status:b.status,changed_by:ctx.user.id});json(res,200,{data})},
 "POST /video-feedback": async(req,res,ctx)=>{if(ctx.profile.role!=="client")return json(res,403,{error:"Client access required."});if(!process.env.SUPABASE_SERVICE_ROLE_KEY)return json(res,503,{error:"Approval workflow requires server storage configuration."});const b=await body(req);const decision=b.action==="approve";if(!b.video_id||(!decision&&!b.feedback))return json(res,400,{error:"Video and revision feedback are required."});const {data:video}=await ctx.supa.from("video_projects").select("id,status").eq("id",b.video_id).single();if(!video||video.status!=="Ready for Review")return json(res,409,{error:"This video is not currently awaiting review."});const {data,error}=await ctx.supa.from("video_feedback").insert({video_id:b.video_id,client_id:ctx.profile.client_id,feedback:b.feedback||"Approved by client.",action:decision?"approved":"changes_requested",created_by:ctx.user.id}).select().single();if(error)return json(res,400,{error:"Could not save feedback."});const admin=createClient(process.env.SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});const {error:updateError}=await admin.from("video_projects").update({status:decision?"Approved":"Changes Requested",approved_at:decision?new Date().toISOString():null,approved_by:decision?ctx.user.id:null}).eq("id",b.video_id).eq("client_id",ctx.profile.client_id);if(updateError)return json(res,500,{error:"Feedback saved, but status update failed."});json(res,201,{data})},
 "GET /calendar": async(req,res,ctx)=>{const q=ctx.profile.role==="admin"?ctx.supa.from("calendar_entries").select("*,clients(business_name)").order("scheduled_at"):ctx.supa.from("calendar_entries").select("*").order("scheduled_at");const {data,error}=await q;return error?json(res,500,{error:"Could not load calendar."}):json(res,200,{data})},
