 "DELETE /calendar": async(req,res,ctx)=>{if(ctx.profile.role!=="admin")return json(res,403,{error:"Admin access required."});const id=new URL(req.url,"http://localhost:4174").searchParams.get("id");const {error}=await ctx.supa.from("calendar_entries").delete().eq("id",id);return error?json(res,400,{error:"Could not remove calendar entry."}):json(res,200,{message:"Calendar entry removed."})},
 "GET /performance": async(req,res,ctx)=>{const q=ctx.profile.role==="admin"?ctx.supa.from("performance_metrics").select("*,clients(business_name)").order("recorded_at",{ascending:false}):ctx.supa.from("performance_metrics").select("*").order("recorded_at",{ascending:false});const {data,error}=await q;return error?json(res,500,{error:"Could not load metrics."}):json(res,200,{data})},
 "POST /performance": async(req,res,ctx)=>{if(ctx.profile.role!=="admin")return json(res,403,{error:"Admin access required."});const b=await body(req);if(!b.client_id||!b.recorded_at)return json(res,400,{error:"Client and reporting date are required."});const {data,error}=await ctx.supa.from("performance_metrics").insert({client_id:b.client_id,video_id:b.video_id||null,video_title:b.video_title||null,instagram_url:b.instagram_url||null,published_at:b.published_at||null,recorded_at:b.recorded_at,followers:b.followers??null,views:b.views??null,reach:b.reach??null,likes:b.likes??null,comments:b.comments??null,shares:b.shares??null,saves:b.saves??null,leads:b.leads??null,calls_booked:b.calls_booked??null,calls_attended:b.calls_attended??null,clients_acquired:b.clients_acquired??null,revenue:b.revenue??null,source:"manual",created_by:ctx.user.id}).select().single();if(error)return json(res,400,{error:"Could not save performance record."});const {data:client}=await ctx.supa.from("profiles").select("id").eq("client_id",b.client_id).single();if(client)await ctx.supa.from("notifications").insert({user_id:client.id,event_type:"performance_report",message:"A new performance report is available in your results.",entity_type:"performance",entity_id:data.id});return json(res,201,{data})},
