Object.assign(routes, {
 "POST /onboarding": async(req,res,ctx)=>{if(ctx.profile.role!=="client"||!ctx.profile.client_id)return json(res,403,{error:"Client workspace is not configured. Ask the agency administrator to reconnect your invitation."});if(!process.env.SUPABASE_SERVICE_ROLE_KEY)return json(res,503,{error:"Onboarding is temporarily unavailable. The administrator must configure the server-side Supabase key."});const b=await body(req),allowed=["basic","instagram","business","baseline","preferences"];if(!allowed.includes(b.step)||!b.response||typeof b.response!=="object"||Array.isArray(b.response))return json(res,400,{error:"Invalid onboarding step or response."});const response=b.response,cid=ctx.profile.client_id,now=new Date().toISOString();if(b.step==="basic"){if(!String(response.full_name||"").trim()||!String(response.business_name||"").trim())return json(res,400,{error:"Add your full name and business name to continue."});const {error:pe}=await ctx.supa.from("profiles").update({full_name:String(response.full_name).trim(),email:ctx.user.email||""}).eq("id",ctx.user.id);if(pe)return json(res,400,{error:"Could not save your profile details."});const {error:ce}=await ctx.supa.from("clients").update({business_name:String(response.business_name).trim(),country:response.country||null,timezone:response.timezone||null,whatsapp:response.whatsapp||null,preferred_contact:response.preferred_contact||null,updated_at:now}).eq("id",cid);if(ce)return json(res,400,{error:"Could not save your business details."})}if(b.step==="instagram"){const followers=numberOrNull(response.followers),views=numberOrNull(response.reel_views);if([followers,views].some(n=>n!==null&&(!Number.isFinite(n)||n<0)))return json(res,400,{error:"Follower and view counts must be non-negative numbers."});const {error}=await ctx.supa.from("clients").update({instagram_username:String(response.username||"").replace(/^@/,"")||null,instagram_url:response.profile_url||null,instagram_account_type:response.account_type||null,current_followers:followers,average_reel_views:views,instagram_notes:response.notes||null,updated_at:now}).eq("id",cid);if(error)return json(res,400,{error:"Could not save your Instagram details."})}if(b.step==="baseline"){const keys={starting_followers:"starting_followers",average_reel_views:"average_reel_views",monthly_leads:"monthly_leads",calls_booked:"calls_booked",calls_attended:"calls_attended",clients_acquired:"clients_acquired",revenue:"monthly_revenue"},baseline={client_id:cid,goal_90_days:response.goal||null,submitted_at:now};for(const [input,column] of Object.entries(keys)){const value=numberOrNull(response[input]);if(value!==null&&(!Number.isFinite(value)||value<0))return json(res,400,{error:"Baseline figures must be non-negative numbers."});baseline[column]=value}const {error}=await ctx.supa.from("performance_baselines").upsert(baseline,{onConflict:"client_id"});if(error)return json(res,400,{error:"Could not save your baseline details."})}const {error:oe}=await ctx.supa.from("onboarding_responses").upsert({client_id:cid,step:b.step,response,submitted_at:response.submitted?now:null,updated_at:now},{onConflict:"client_id,step"});if(oe)return json(res,400,{error:"Your answers could not be saved. Please retry; your current page is still open."});const admin=createClient(process.env.SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}}),status=response.submitted?"submitted":"in_progress";const {error:se}=await admin.from("clients").update({onboarding_status:status,updated_at:now}).eq("id",cid);if(se)return json(res,500,{error:"Your answers were saved, but the workspace status could not be updated. Contact the agency administrator."});if(response.submitted){const {data:admins}=await admin.from("profiles").select("id").eq("role","admin");if(admins?.length)await admin.from("notifications").insert(admins.map(a=>({user_id:a.id,event_type:"onboarding_submitted",message:"A client completed onboarding.",entity_type:"client",entity_id:cid})))}return json(res,200,{message:response.submitted?"Onboarding submitted.":"Progress saved."})},
 "GET /booking-link": async(req,res,ctx)=>{const u=new URL(req.url,"http://localhost:4174"),requested=u.searchParams.get("client_id"),clientId=ctx.profile.role==="admin"?requested:ctx.profile.client_id;if(!clientId)return json(res,400,{error:"Client is required."});const {data,error}=await ctx.supa.from("clients").select("id,business_name,booking_url").eq("id",clientId).maybeSingle();if(error)return json(res,500,{error:"Could not load booking link."});if(!data)return json(res,404,{error:"Client was not found."});return json(res,200,{booking_url:data.booking_url,tracked_url:data.booking_url?trackedBookingURL(data.id):null})},
 "PUT /booking-link": async(req,res,ctx)=>{if(ctx.profile.role!=="admin")return json(res,403,{error:"Admin access required."});const b=await body(req);if(!uuidPattern.test(String(b.client_id||"")))return json(res,400,{error:"A valid client is required."});const destination=String(b.booking_url||"").trim();if(destination&&!calendlyURL(destination))return json(res,400,{error:"Use an HTTPS Calendly booking URL."});const {data,error}=await ctx.supa.from("clients").update({booking_url:destination||null,updated_at:new Date().toISOString()}).eq("id",b.client_id).select("id,booking_url").single();return error?json(res,400,{error:"Could not save booking destination. Apply the latest database migration first."}):json(res,200,{booking_url:data.booking_url,tracked_url:data.booking_url?trackedBookingURL(data.id):null})},
 "GET /performance": async(req,res,ctx)=>{const admin=ctx.profile.role==="admin",q=admin?ctx.supa.from("performance_metrics").select("*,clients(business_name)").order("recorded_at",{ascending:false}):ctx.supa.from("performance_metrics").select("*").order("recorded_at",{ascending:false});const [m,c,b]=await Promise.all([q,ctx.supa.from("booking_click_events").select("client_id"),ctx.supa.from("booking_events").select("client_id").eq("status","active")]);if(m.error||c.error||b.error)return json(res,500,{error:"Could not load performance metrics. Apply the latest database migration first."});const clicks={},bookings={};for(const x of c.data||[])clicks[x.client_id]=(clicks[x.client_id]||0)+1;for(const x of b.data||[])bookings[x.client_id]=(bookings[x.client_id]||0)+1;return json(res,200,{data:m.data||[],booking_stats:admin?{by_client:Object.keys({...clicks,...bookings}).map(id=>({client_id:id,clicks:clicks[id]||0,bookings:bookings[id]||0}))}:{clicks:clicks[ctx.profile.client_id]||0,bookings:bookings[ctx.profile.client_id]||0}})},
 "POST /performance": async(req,res,ctx)=>{if(ctx.profile.role!=="admin")return json(res,403,{error:"Admin access required."});const b=await body(req);if(!b.client_id||!b.recorded_at)return json(res,400,{error:"Client and reporting date are required."});const fields=["followers","follows","unfollows","profile_link_taps","accounts_engaged","total_interactions","views","reach","likes","comments","shares","saves","leads","calls_booked","calls_attended","clients_acquired","revenue"],metric={client_id:b.client_id,video_id:b.video_id||null,video_title:b.video_title||null,instagram_url:b.instagram_url||null,published_at:b.published_at||null,recorded_at:b.recorded_at,source:"manual",created_by:ctx.user.id};for(const key of fields)metric[key]=b[key]===""||b[key]==null?null:Number(b[key]);if(fields.some(k=>metric[k]!=null&&(!Number.isFinite(metric[k])||metric[k]<0)))return json(res,400,{error:"Metric values must be non-negative numbers."});const {data,error}=await ctx.supa.from("performance_metrics").insert(metric).select().single();if(error)return json(res,400,{error:"Could not save performance record. Apply the latest database migration first."});const {data:client}=await ctx.supa.from("profiles").select("id").eq("client_id",b.client_id).single();if(client)await ctx.supa.from("notifications").insert({user_id:client.id,event_type:"performance_report",message:"A new performance report is available in your results.",entity_type:"performance",entity_id:data.id});return json(res,201,{data})}
});

export default async function handler(req,res) {
 const url=new URL(req.url,"http://localhost:4174");
 const pathname=url.searchParams.has("__fa_route")?`/${url.searchParams.get("__fa_route")}`:url.pathname;
 if(pathname.startsWith("/api/")){
  const key=`${req.method} /${pathname.slice(5)}`;
  if(req.method==="GET"&&pathname.startsWith("/api/book/")){try{return await bookingRedirect(decodeURIComponent(pathname.slice("/api/book/".length)),res)}catch{return publicJson(res,500,{error:"Could not open this booking link."})}}
  if(key==="POST /webhooks/calendly"){try{return await calendlyWebhook(req,res)}catch{return publicJson(res,500,{error:"Could not process Calendly webhook."})}}
  if(key==="POST /auth/login"||key==="POST /auth/refresh"||key==="POST /auth/reset"||key==="POST /auth/verify-invite"||key==="GET /meta/callback"){
   if(!process.env.SUPABASE_URL||!process.env.SUPABASE_ANON_KEY)return json(res,503,{error:"Supabase is not configured. Add the required environment variables."});
   try{return await routes[key](req,res)}catch{return json(res,500,{error:"Request could not be completed."})}
  }
  if(!process.env.SUPABASE_URL||!process.env.SUPABASE_ANON_KEY)return json(res,503,{error:"Supabase is not configured. Add the required environment variables."});
  const ctx=await authUser(req);if(!ctx)return json(res,401,{error:"Please sign in."});
  if(!routes[key])return json(res,404,{error:"API route not found."});
  try{return await routes[key](req,res,ctx)}catch{return json(res,500,{error:"Request could not be completed."})}
 }
 if(pathname==="/login")return sendHtml(res,loginPage(pathname));
 if(pathname==="/invite"||pathname==="/reset")return sendHtml(res,credentialPage(pathname));
 const area=pathname.startsWith("/admin")?"admin":pathname.startsWith("/portal")?"client":null;
 if(!area){res.writeHead(404,{"content-type":"text/plain"});return res.end("Not found")}
 const page=area==="admin"?adminPage(pathname):clientPage(pathname);
 return sendHtml(res,`<script>if(!sessionStorage.getItem('fa_token'))location.replace('/login?next=${encodeURIComponent(pathname)}');</script>${page}`);
}

function sendHtml(res,html){const nonce=randomBytes(18).toString("base64");const page=html.replaceAll("<script>",`<script nonce="${nonce}">`);res.writeHead(200,{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","x-frame-options":"DENY","content-security-policy":`default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; script-src 'self' 'nonce-${nonce}'; img-src 'self' data: blob:; media-src 'self' blob:; connect-src 'self' https://*.supabase.co`});res.end(page)}

function loginPage(path){
 const body=`<main class="login card"><a class="brand" href="/">force<b>aim</b></a><p class="eyebrow">PRIVATE WORKSPACE</p><h1>${path==="/reset"?"Reset your password":"Welcome back"}</h1><p class="muted">Sign in to your ForceAim workspace.</p><form class="form" id="loginForm"><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required autocomplete="current-password" minlength="8"></label><button class="btn">Sign in</button><a href="#" id="forgot" class="muted">Forgot your password?</a><div data-message class="notice" hidden></div></form><p class="muted">Client accounts are created by invitation.</p><a href="/" class="muted">← Back to the ForceAim client platform</a></main><script>const f=document.getElementById('loginForm');f.addEventListener('submit',e=>submitForm(e,async fd=>{const d=await req('/auth/login',{method:'POST',body:JSON.stringify({email:fd.get('email'),password:fd.get('password')})});sessionStorage.setItem('fa_token',d.token);sessionStorage.setItem('fa_refresh',d.refresh_token);const me=await req('/me');location.href=new URLSearchParams(location.search).get('next')||(me.profile.role==='admin'?'/admin':'/portal');return d}));document.getElementById('forgot').onclick=async e=>{e.preventDefault();const email=f.elements.email.value;if(!email)return alert('Enter your email address first.');try{const d=await req('/auth/reset',{method:'POST',body:JSON.stringify({email})});alert(d.message)}catch(x){alert(x.message)}};</script>`;
 return appHtml("Sign in",body);
}
function credentialPage(path){const recovery=path==="/reset",title=recovery?"Reset password":"Accept invitation";const body=`<main class="login card"><a class="brand" href="/">force<b>aim</b></a><p class="eyebrow">PRIVATE WORKSPACE</p><h1>${title}</h1><p class="muted">${recovery?"Choose a new password for your ForceAim account.":"Set a password to open your client workspace."}</p><form id="passwordForm" class="form"><label>New password<input type="password" name="password" required minlength="12" autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirm" required minlength="12" autocomplete="new-password"></label><button class="btn">Save password</button><div data-message class="notice" hidden></div></form><a href="/login" class="muted">Back to sign in</a></main><script>const params=new URLSearchParams(location.search),hash=new URLSearchParams(location.hash.slice(1));let initialized=Promise.resolve();if(hash.get('access_token')){sessionStorage.setItem('fa_token',hash.get('access_token'));sessionStorage.setItem('fa_refresh',hash.get('refresh_token')||'')}else if(params.get('token_hash')){initialized=req('/auth/verify-invite',{method:'POST',body:JSON.stringify({token_hash:params.get('token_hash'),type:params.get('type')||'${recovery?'recovery':'invite'}'})}).then(d=>{sessionStorage.setItem('fa_token',d.token);sessionStorage.setItem('fa_refresh',d.refresh_token)})}else if(params.get('error'))initialized=Promise.reject(Error('This link is invalid or expired. Request a new invitation or password reset.'));document.getElementById('passwordForm').addEventListener('submit',e=>submitForm(e,async fd=>{await initialized;if(fd.get('password')!==fd.get('confirm'))throw Error('The passwords do not match.');const d=await req('/auth/set-password',{method:'POST',body:JSON.stringify({password:fd.get('password')})});const me=await req('/me');location.href=me.profile.role==='admin'?'/admin':'/portal';return d}));</script>`;return appHtml(title,body)}
function adminPage(path){if(path.startsWith("/admin/clients/"))return adminClientWorkspace(path.split("/")[3]);const section=path.split("/")[2]||"overview";const title={overview:"Overview",clients:"Clients",references:"Reference Library",videos:"Video Projects",calendar:"Content Calendar",performance:"Performance Reports",activity:"Activity",notifications:"Notifications",settings:"Settings"}[section]||"Overview";let inner="";
 if(section==="overview")inner=`<div class="grid" id="stats"></div><section class="columns section"><div class="card"><h2>Upcoming scheduled content</h2><div id="upcoming"><div class="empty">Loading…</div></div></div><div class="card"><h2>Recently updated reports</h2><div id="reports"><div class="empty">Loading…</div></div></div></section><section class="section"><h2>Client activity</h2><div class="card" id="recent"><div class="empty">Loading records…</div></div></section><script>protect().then(()=>req('/dashboard')).then(d=>{const clients=d.data||[],s=d.summary||{};document.getElementById('stats').innerHTML=[["Total clients",s.clients??0],["Onboarding in progress",s.onboarding??0],["Incomplete onboarding",s.incomplete??0],["New video submissions",s.submissions??0],["Queued for editing",s.queued??0],["Awaiting approval",s.review??0],["Revision requests",s.revisions??0],["Upcoming content",s.upcoming??0]].map(x=>'<article class="card"><span class="muted">'+safe(x[0])+'</span><div class="metric">'+safe(x[1])+'</div></article>').join('');document.getElementById('recent').innerHTML=clients.length?clients.slice(0,6).map(c=>'<div class="row"><a href="/admin/clients/'+safe(c.id)+'">'+safe(c.business_name)+'</a><span class="badge">'+safe(c.onboarding_status||'Onboarding pending')+'</span></div>').join(''):'<div class="empty">No clients yet. Invite your first client to begin.</div>';document.getElementById('upcoming').innerHTML=d.upcoming?.length?d.upcoming.slice(0,6).map(x=>'<div class="row"><span>'+safe(x.title)+'</span><span class="badge">'+safe(new Date(x.scheduled_at).toLocaleDateString())+'</span></div>').join(''):'<div class="empty">No scheduled content coming up.</div>';document.getElementById('reports').innerHTML=d.reports?.length?d.reports.map(x=>'<div class="row"><span>'+safe(x.clients?.business_name||'Client')+'</span><span class="badge">'+safe(x.recorded_at)+'</span></div>').join(''):'<div class="empty">No performance reports have been added.</div>'}).catch(showError)</script>`;
 if(section==="clients")inner=`<section class="card"><div class="top"><h2>Client directory</h2><button class="btn" type="button" id="inviteToggle" aria-expanded="false">Invite client</button></div><input id="search" placeholder="Search clients"><div id="clientRows" class="section"><div class="empty">Loading clients…</div></div></section><section class="card section" id="invite" hidden><h2>Invite a client</h2><form id="inviteForm" class="form" method="post"><div class="columns"><label>Full name<input name="full_name" required></label><label>Email<input name="email" type="email" required></label></div><label>Business name<input name="business_name" required></label><label>Country<input name="country"></label><button class="btn">Send invitation</button><div class="notice" data-message hidden></div></form></section><script>const invitePanel=document.getElementById('invite'),inviteButton=document.getElementById('inviteToggle');inviteButton.onclick=()=>{invitePanel.hidden=!invitePanel.hidden;inviteButton.setAttribute('aria-expanded',String(!invitePanel.hidden));if(!invitePanel.hidden){invitePanel.scrollIntoView({behavior:'smooth',block:'start'});invitePanel.querySelector('input').focus()}};protect().then(()=>req('/clients')).then(d=>{const cs=d.data||[];function draw(){const q=document.getElementById('search').value.toLowerCase();const a=cs.filter(c=>(c.business_name+' '+(c.profiles?.full_name||'')).toLowerCase().includes(q));document.getElementById('clientRows').innerHTML=a.length?'<table class="table"><thead><tr><th>Client</th><th>Business</th><th>Onboarding</th><th>Videos</th></tr></thead><tbody>'+a.map(c=>'<tr><td><a href="/admin/clients/'+safe(c.id)+'">'+safe((c.profiles||{}).full_name||'—')+'</a></td><td><a href="/admin/clients/'+safe(c.id)+'">'+safe(c.business_name)+'</a></td><td>'+safe(c.onboarding_status||'Not started')+'</td><td>'+((c.video_projects||[]).length)+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No clients yet. Use Invite client to add one.</div>'}document.getElementById('search').oninput=draw;draw()}).catch(e=>{document.getElementById('clientRows').innerHTML='<div class="notice error">Could not load clients: '+safe(e.message)+'. You can still open the invitation form.</div>'});document.getElementById('inviteForm').addEventListener('submit',e=>submitForm(e,fd=>req('/clients',{method:'POST',body:JSON.stringify(Object.fromEntries(fd))}).then(d=>{setTimeout(()=>location.reload(),900);return d})))</script>`;
 if(section==="references")inner=`<section class="card"><h2>New reference</h2><form id="refForm" class="form"><input type="hidden" name="id"><input type="hidden" name="video_storage_path"><div class="columns"><label>Reference title<input name="title" required></label><label>Category<select name="category">${["Educational","Storytelling","Authority","Personal brand","Lead generation","Offer promotion","Case study","Other"].map(x=>`<option>${x}</option>`).join("")}</select></label></div><div class="columns"><label>Instagram Reel URL<input name="instagram_url" type="url"></label><label>YouTube URL<input name="youtube_url" type="url"></label></div><label>Description<textarea name="description"></textarea></label><label>Hook analysis<textarea name="hook_analysis"></textarea></label><label>Storytelling structure<textarea name="storytelling_structure"></textarea></label><label>Recording instructions<textarea name="recording_instructions"></textarea></label><label>Caption style<textarea name="caption_style"></textarea></label><label>Editing instructions<textarea name="editing_instructions"></textarea></label><label>Animation and transition notes<textarea name="animation_notes"></textarea></label><label>Private content strategy notes<textarea name="content_notes"></textarea></label><label>Reference video file<input type="file" id="refVideo" accept="video/mp4,video/quicktime,.mp4,.mov"></label><button class="btn">Save draft</button><div data-message class="notice" hidden></div></form></section><section class="section"><h2>Reference library</h2><div id="refs" class="grid"><div class="empty">Loading…</div></div></section><script>let clientList=[];protect().then(async()=>{const [r,c]=await Promise.all([req('/references'),req('/clients')]);clientList=c.data||[];renderRefs(r.data||[])}).catch(showError);function renderRefs(a){document.getElementById('refs').innerHTML=a.length?a.map(x=>'<article class="card"><span class="badge">'+safe(x.category)+' · '+safe(x.status)+'</span><h2>'+safe(x.title)+'</h2><p class="muted">'+safe(x.description||'')+'</p><div class="muted">Assigned to: '+((x.client_references||[]).map(c=>safe(c.clients?.business_name||'client')).join(', ')||'No clients')+'</div><div class="columns section"><select id="client-'+safe(x.id)+'">'+clientList.map(c=>'<option value="'+safe(c.id)+'">'+safe(c.business_name)+'</option>').join('')+'</select><button class="btn ghost" data-assign="'+safe(x.id)+'">Assign / publish</button></div><div class="row"><button class="btn ghost" data-edit="'+safe(x.id)+'">Edit</button><button class="btn ghost" data-duplicate="'+safe(x.id)+'">Duplicate</button><button class="btn danger" data-delete="'+safe(x.id)+'">Delete</button></div></article>').join(''):'<div class="empty">No references yet. Add a draft above.</div>';document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=async()=>{try{const id=b.dataset.assign,select=document.getElementById('client-'+id);await req('/assign-reference',{method:'POST',body:JSON.stringify({reference_id:id,client_id:select.value,published:true})});const d=await req('/references');renderRefs(d.data||[])}catch(e){alert(e.message)}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const x=a.find(r=>r.id===b.dataset.edit),f=document.getElementById('refForm');if(!x)return;for(const k of ['id','title','category','instagram_url','youtube_url','description','hook_analysis','storytelling_structure','recording_instructions','caption_style','editing_instructions','animation_notes','video_storage_path'])if(f.elements[k])f.elements[k].value=x[k]||'';f.elements.content_notes.value=x.reference_private_notes?.[0]?.note||'';f.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-unpublish]').forEach(b=>b.onclick=async()=>{const [reference_id,client_id]=b.dataset.unpublish.split(':');try{await req('/assign-reference',{method:'POST',body:JSON.stringify({reference_id,client_id,published:false})});const d=await req('/references');renderRefs(d.data||[])}catch(e){alert(e.message)}});document.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=async()=>{try{await req('/reference-duplicate',{method:'POST',body:JSON.stringify({reference_id:b.dataset.duplicate})});const d=await req('/references');renderRefs(d.data||[])}catch(e){alert(e.message)}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this reference?'))return;try{await req('/references?id='+encodeURIComponent(b.dataset.delete),{method:'DELETE'});const d=await req('/references');renderRefs(d.data||[])}catch(e){alert(e.message)}})}document.getElementById('refForm').addEventListener('submit',e=>submitForm(e,async fd=>{const file=document.getElementById('refVideo').files[0];let video_storage_path=fd.get('video_storage_path')||null;if(file){const u=await req('/reference-upload-token',{method:'POST',body:JSON.stringify({filename:file.name,size:file.size,type:file.type})});await uploadSigned(u.url,file);video_storage_path=u.path}const values=Object.fromEntries(fd);values.video_storage_path=video_storage_path;const d=await req('/references',{method:values.id?'PUT':'POST',body:JSON.stringify(values)});const refs=await req('/references');renderRefs(refs.data||[]);return {message:'Reference draft saved.'}}))</script>`;
 if(["videos","calendar","performance","activity","notifications","settings"].includes(section))inner=adminDataPage(section);
 return layout("admin",title,title,section==="overview"?"A clear view of client work, production, and upcoming content.":`Manage ${title.toLowerCase()} across your client workspaces.`,inner);
}
function adminClientWorkspace(id){const inner=`<nav class="tabs"><a class="btn ghost" href="#client-overview">Overview</a><a class="btn ghost" href="#client-info">Client information</a><a class="btn ghost" href="#client-instagram">Instagram</a><a class="btn ghost" href="#client-references">References</a><a class="btn ghost" href="#client-videos">Videos</a><a class="btn ghost" href="#client-calendar">Calendar</a><a class="btn ghost" href="#client-performance">Performance</a><a class="btn ghost" href="#client-notes">Private notes</a></nav><div id="clientWorkspace"><div class="empty">Loading client workspace…</div></div><script>protect().then(()=>req('/client?id='+encodeURIComponent('${esc(id)}'))).then(({data:c})=>{const p=c.profiles||{},ig=c.instagram_connections?.[0]||{},bas=c.performance_baselines?.[0]||{},on=c.onboarding_responses||[],refs=c.client_references||[],videos=c.video_projects||[],events=c.calendar_entries||[],metrics=c.performance_metrics||[],notes=c.client_private_notes||[];document.getElementById('clientWorkspace').innerHTML='<section id="client-overview" class="section"><div class="grid">'+[["Business",c.business_name],["Onboarding",c.onboarding_status],["Followers",c.current_followers??'—'],["Active videos",videos.filter(v=>!['Approved','Published'].includes(v.status)).length]].map(x=>'<article class="card"><span class="muted">'+safe(x[0])+'</span><div class="metric">'+safe(x[1])+'</div></article>').join('')+'</div></section><section id="client-info" class="card section"><h2>Client information</h2><div class="row"><span>Name</span><b>'+safe(p.full_name||'—')+'</b></div><div class="row"><span>Email</span><b>'+safe(p.email||'—')+'</b></div><div class="row"><span>Business</span><b>'+safe(c.business_name)+'</b></div><div class="row"><span>Country / time zone</span><b>'+safe(c.country||'—')+' · '+safe(c.timezone||'—')+'</b></div><div class="row"><span>WhatsApp / contact method</span><b>'+safe(c.whatsapp||'—')+' · '+safe(c.preferred_contact||'—')+'</b></div></section><section id="client-instagram" class="card section"><h2>Instagram account</h2><div class="row"><span>Profile</span><b>'+safe(c.instagram_username?'@'+c.instagram_username:'—')+'</b></div><div class="row"><span>Followers / average Reel views</span><b>'+safe(c.current_followers??'—')+' / '+safe(c.average_reel_views??'—')+'</b></div><div class="row"><span>Meta connection</span><span class="badge">'+safe(ig.status||'Not connected')+'</span></div></section><section id="client-references" class="card section"><h2>Assigned references</h2>'+ (refs.length?refs.map(x=>'<div class="row"><b>'+safe(x.content_references?.title||'Reference')+'</b><span class="badge">'+(x.published?'Published':'Draft')+'</span></div>').join(''):'<div class="empty">No references assigned.</div>')+'</section><section id="client-videos" class="card section"><h2>Video projects</h2>'+ (videos.length?videos.map(v=>'<div class="row"><span><b>'+safe(v.title)+'</b><br><small>'+safe(v.status)+'</small></span><button class="btn ghost" data-raw="'+safe(v.id)+'">Preview raw</button></div>'+((v.video_versions||[]).map(ver=>'<div class="row"><span>Edited version '+safe(ver.version_number)+'</span><button class="btn ghost" data-version-url="'+safe(ver.id)+'">Open edited</button></div>').join(''))).join(''):'<div class="empty">No videos submitted.</div>')+'</section><section id="client-calendar" class="card section"><h2>Content calendar</h2>'+ (events.length?events.map(e=>'<div class="row"><span>'+safe(e.title)+' · '+safe(e.scheduled_at||'Not scheduled')+'</span><span class="badge">'+safe(e.status)+'</span></div>').join(''):'<div class="empty">No calendar entries.</div>')+'</section><section id="client-performance" class="card section"><h2>Performance</h2>'+ (metrics.length?metrics.map(m=>'<div class="row"><span>'+safe(m.recorded_at)+' · Followers '+safe(m.followers??'—')+' · Views '+safe(m.views??'—')+'</span><span class="badge">'+safe(m.source)+'</span></div>').join(''):'<div class="empty">No performance records.</div>')+'<p class="muted">Baseline: followers '+safe(bas.starting_followers??'—')+', monthly leads '+safe(bas.monthly_leads??'—')+', calls booked '+safe(bas.calls_booked??'—')+'</p></section><section id="client-notes" class="card section"><h2>Private agency notes</h2><form class="form" id="noteForm"><label>Add private note<textarea name="note" required></textarea></label><button class="btn">Save note</button><div data-message class="notice" hidden></div></form>'+ (notes.length?notes.map(n=>'<div class="notice">'+safe(new Date(n.created_at).toLocaleString())+'<br>'+safe(n.note)+'</div>').join(''):'<div class="muted">No internal notes.</div>')+'</section>';const instagramPanel=document.getElementById('client-instagram');const metaNotice=document.createElement('div');metaNotice.className='notice';const metaResult=new URLSearchParams(location.search).get('meta');const metaMessages={connected:'Instagram was connected successfully through Meta.',denied:'Instagram authorization was cancelled or denied.',setup:'Meta connection is not configured yet. Add the required server-side Meta settings and redeploy.',state:'The authorization expired or could not be verified. Start the connection again.',account:'The authorization could not be matched to this client workspace.',exchange:'Meta did not return a usable access token. Check the Meta app setup and try again.',profile:'Meta authorized the account but its profile could not be retrieved.',save:'Meta authorized the account, but the connection could not be safely saved.',error:'Instagram could not be connected. Try again or check the function logs.'};if(metaMessages[metaResult]){metaNotice.textContent=metaMessages[metaResult];instagramPanel.appendChild(metaNotice)}const metaControls=document.createElement('div');metaControls.className='section';const connectedInstagram=ig.status==='connected';metaControls.innerHTML='<p class="muted">'+(connectedInstagram?'Connected as @'+safe(ig.username||'Instagram account')+' · '+safe(ig.status):'No Meta Instagram account is connected to this client yet.')+'</p><div class="row"><button type="button" class="btn" data-meta-action="connect">'+(connectedInstagram?'Reconnect Instagram':'Connect Instagram through Meta')+'</button>'+(connectedInstagram?'<button type="button" class="btn ghost" data-meta-action="refresh">Refresh connection</button><button type="button" class="btn danger" data-meta-action="disconnect">Disconnect</button>':'')+'</div><div class="muted">The account owner must sign in and authorize access on Instagram. ForceAim never asks for Instagram passwords or security codes.</div><div class="notice" data-meta-message hidden></div>';instagramPanel.appendChild(metaControls);metaControls.querySelectorAll('[data-meta-action]').forEach(button=>button.addEventListener('click',async()=>{const action=button.dataset.metaAction;const message=metaControls.querySelector('[data-meta-message]');message.hidden=false;message.textContent=action==='connect'?'Opening Instagram authorization…':'Working…';try{if(action==='connect'){const result=await req('/meta/connect?client_id='+encodeURIComponent(c.id));if(!result.authorization_url)throw Error('Meta did not provide an authorization link.');location.assign(result.authorization_url);return}if(action==='disconnect'&&!confirm('Disconnect this client’s Instagram account?')){message.hidden=true;return}const result=await req('/meta/'+action,{method:'POST',body:JSON.stringify({client_id:c.id})});message.textContent=result.message||'Updated.';setTimeout(()=>location.reload(),500)}catch(error){message.textContent=error.message||'Instagram action failed.'}}));document.querySelectorAll('[data-raw]').forEach(b=>b.onclick=async()=>{const d=await req('/video-url?id='+encodeURIComponent(b.dataset.raw));window.open(d.url,'_blank','noopener')});document.querySelectorAll('[data-version-url]').forEach(b=>b.onclick=async()=>{const d=await req('/version-url?id='+encodeURIComponent(b.dataset.versionUrl));window.open(d.url,'_blank','noopener')});document.getElementById('noteForm').addEventListener('submit',e=>submitForm(e,fd=>req('/client-note',{method:'POST',body:JSON.stringify({client_id:c.id,note:fd.get('note')})}).then(d=>{setTimeout(()=>location.reload(),700);return d}))) }).catch(showError)</script>`;return layout("admin","Clients", "Client workspace", "Manage private client details and ongoing work.",inner)}
function adminDataPage(section){const path={videos:"videos",calendar:"calendar",performance:"performance",activity:"activity",notifications:"notifications"}[section];const heading={videos:"Video production queue",calendar:"Publishing calendar",performance:"Performance records",activity:"Recent activity",notifications:"Notifications",settings:"Workspace settings"}[section];if(section==="settings")return `<section class="card"><h2>Workspace configuration</h2><p class="muted">Application credentials are managed through Netlify environment variables. Never add service keys to browser configuration.</p><p>Administrator provisioning uses the Supabase SQL migration and first-admin instructions in PLATFORM.md.</p></section>`;if(section==="calendar")return adminCalendarPage();if(section==="performance")return adminPerformancePage();if(section==="notifications")return notificationsPage();if(section==="videos")return `<section id="videoQueue" class="calendar"><div class="empty">Loading video projects…</div></section><script>protect().then(()=>req('/videos')).then(d=>{const a=d.data||[];document.getElementById('videoQueue').innerHTML=a.length?a.map(v=>'<article class="card"><div class="row"><div><h2>'+safe(v.title)+'</h2><div class="muted">'+safe(v.clients?.business_name||'Client')+' · '+safe(v.status)+'</div></div><span class="badge">'+safe(v.status)+'</span></div><p>'+safe(v.description||'')+'</p><p class="muted">Recording notes: '+safe(v.recording_notes||'—')+'</p><div class="row"><button class="btn ghost" data-raw="'+safe(v.id)+'">Preview / download raw</button><select data-status="'+safe(v.id)+'">${["Uploaded","Queued for Editing","Editing","Ready for Review","Changes Requested","Approved","Ready to Publish","Published"].map(s=>`<option value="${s}">${s}</option>`).join("")}</select><button class="btn ghost" data-save-status="'+safe(v.id)+'">Update status</button></div><video id="raw-'+safe(v.id)+'" controls hidden style="width:100%;max-height:440px;margin:12px 0"></video><div class="section"><b>Client feedback</b>'+(v.video_feedback||[]).map(f=>'<div class="notice">'+safe(f.action)+': '+safe(f.feedback)+'</div>').join('')+(v.video_feedback?.length?'':'<p class="muted">No feedback submitted.</p>')+'</div><div class="columns"><form class="form note-form" data-note="'+safe(v.id)+'"><label>Private agency note<textarea name="note" required></textarea></label><button class="btn ghost">Save private note</button></form><form class="form version-form" data-version="'+safe(v.id)+'"><label>Edited MP4 file<input type="file" name="file" accept="video/mp4" required></label><button class="btn">Upload edit and send for review</button></form></div>'+(v.video_private_notes||[]).map(n=>'<div class="notice"><b>Agency note</b> · '+safe(new Date(n.created_at).toLocaleString())+'<br>'+safe(n.note)+'</div>').join('')+'<div class="section"><b>Version history</b>'+((v.video_versions||[]).map(x=>'<div class="row"><span>Version '+safe(x.version_number)+' · '+safe(new Date(x.created_at).toLocaleDateString())+'</span><button class="btn ghost" data-version-url="'+safe(x.id)+'">Preview / download</button></div>').join('')||'<div class="muted">No edited versions yet.</div>')+'</div></article>').join(''):'<div class="empty">No raw footage has been submitted yet.</div>';document.querySelectorAll('[data-raw]').forEach(b=>b.onclick=async()=>{try{const d=await req('/video-url?id='+encodeURIComponent(b.dataset.raw));const v=document.getElementById('raw-'+b.dataset.raw);v.src=d.url;v.hidden=false;await v.play()}catch(e){alert(e.message)}});document.querySelectorAll('[data-version-url]').forEach(b=>b.onclick=async()=>{try{const d=await req('/version-url?id='+encodeURIComponent(b.dataset.versionUrl));window.open(d.url,'_blank','noopener')}catch(e){alert(e.message)}});document.querySelectorAll('[data-save-status]').forEach(b=>b.onclick=async()=>{try{await req('/video-status',{method:'POST',body:JSON.stringify({video_id:b.dataset.saveStatus,status:document.querySelector('[data-status="'+b.dataset.saveStatus+'"]').value})});location.reload()}catch(e){alert(e.message)}});document.querySelectorAll('.note-form').forEach(f=>f.addEventListener('submit',e=>submitForm(e,fd=>req('/video-note',{method:'POST',body:JSON.stringify({video_id:f.dataset.note,note:fd.get('note')})}).then(d=>{setTimeout(()=>location.reload(),700);return d}))));document.querySelectorAll('.version-form').forEach(f=>f.addEventListener('submit',e=>submitForm(e,async fd=>{const file=fd.get('file');if(!file||file.type!=='video/mp4')throw Error('Choose an MP4 video.');const u=await req('/video-version-token',{method:'POST',body:JSON.stringify({video_id:f.dataset.version})});await uploadSigned(u.url,file);await req('/video-version',{method:'POST',body:JSON.stringify({video_id:f.dataset.version,storage_path:u.path})});await req('/video-status',{method:'POST',body:JSON.stringify({video_id:f.dataset.version,status:'Ready for Review'})});return {message:'Edit uploaded and sent for client review.'}})))}).catch(showError)</script>`;return `<section class="card"><h2>${heading}</h2><div id="data" class="empty">Loading…</div></section><script>protect().then(()=>req('/${path}')).then(d=>{const a=d.data||[];document.getElementById('data').innerHTML=a.length?a.map(x=>'<div class="row"><div><b>'+safe(x.title||x.business_name||x.event_type||x.status)+'</b><div class="muted">'+safe(x.clients?.business_name||x.status||x.created_at||'')+'</div></div><span class="badge">'+safe(x.status||x.source||'Record')+'</span></div>').join(''):'<div class="empty">No records yet.</div>'}).catch(showError)</script>`}
function adminCalendarPage(){return `<div class="columns"><section class="card"><h2>Schedule content</h2><form id="calendarForm" class="form"><label>Client<select name="client_id" id="calendarClient" required></select></label><label>Content title<input name="title" required></label><div class="columns"><label>Platform<select name="platform"><option>Instagram</option><option>YouTube</option><option>TikTok</option></select></label><label>Publish date<input name="scheduled_at" type="datetime-local"></label></div><label>Status<select name="status">${["Idea","Reference Assigned","Awaiting Recording","Editing","Awaiting Approval","Approved","Scheduled","Published"].map(x=>`<option>${x}</option>`).join("")}</select></label><label>Notes<textarea name="notes"></textarea></label><button class="btn">Add calendar entry</button><div data-message class="notice" hidden></div></form></section><section class="card"><h2>Calendar workflow</h2><p class="muted">Entries are planning records. Scheduled or published status reflects the actual workflow state you set.</p><div class="notice">Instagram publishing is not automated by this platform.</div></section></div><section class="section"><h2>Upcoming and planned content</h2><div id="calendarRows" class="calendar"><div class="empty">Loading…</div></div></section><script>let clients=[];protect().then(async()=>{const [c,d]=await Promise.all([req('/clients'),req('/calendar')]);clients=c.data||[];document.getElementById('calendarClient').innerHTML=clients.map(x=>'<option value="'+safe(x.id)+'">'+safe(x.business_name)+'</option>').join('');drawCalendar(d.data||[])}).catch(showError);function drawCalendar(a){document.getElementById('calendarRows').innerHTML=a.length?a.map(x=>'<form class="card calendar-edit" data-id="'+safe(x.id)+'" data-status="'+safe(x.status)+'"><div class="row"><div><b>'+safe(x.title)+'</b><div class="muted">'+safe(x.clients?.business_name||'Client')+' · '+safe(x.platform)+'</div></div><span class="badge">'+safe(x.status)+'</span></div><div class="columns"><label>Date<input name="scheduled_at" type="datetime-local" value="'+(x.scheduled_at?new Date(x.scheduled_at).toISOString().slice(0,16):'')+'"></label><label>Status<select name="status">${["Idea","Reference Assigned","Awaiting Recording","Editing","Awaiting Approval","Approved","Scheduled","Published"].map(s=>`<option value="${s}">${s}</option>`).join("")}</select></label></div><label>Notes<textarea name="notes">'+safe(x.notes||'')+'</textarea></label><button class="btn ghost">Save changes</button> <button type="button" class="btn danger" data-remove="'+safe(x.id)+'">Remove</button></form>').join(''):'<div class="empty">No calendar entries yet.</div>';document.querySelectorAll('.calendar-edit').forEach(f=>f.addEventListener('submit',e=>submitForm(e,fd=>req('/calendar',{method:'PUT',body:JSON.stringify({...Object.fromEntries(fd),id:f.dataset.id,scheduled_at:fd.get('scheduled_at')?new Date(fd.get('scheduled_at')).toISOString():null})}).then(d=>{setTimeout(()=>location.reload(),700);return d}))));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this calendar entry?'))return;await req('/calendar?id='+b.dataset.remove,{method:'DELETE'});location.reload()})}document.getElementById('calendarForm').addEventListener('submit',e=>submitForm(e,fd=>req('/calendar',{method:'POST',body:JSON.stringify({...Object.fromEntries(fd),scheduled_at:fd.get('scheduled_at')?new Date(fd.get('scheduled_at')).toISOString():null})}).then(d=>{setTimeout(()=>location.reload(),700);return d})))</script>`}
function legacyAdminPerformancePage(){return `<section class="card"><h2>Add a manual performance report</h2><form id="metricForm" class="form"><div class="columns"><label>Client<select name="client_id" id="metricClient" required></select></label><label>Report date<input type="date" name="recorded_at" required></label></div><div class="columns"><label>Video title<input name="video_title"></label><label>Instagram Reel URL<input type="url" name="instagram_url"></label><label>Publication date<input type="date" name="published_at"></label></div><div class="grid">${[["followers","Followers"],["views","Views"],["reach","Reach"],["likes","Likes"],["comments","Comments"],["shares","Shares"],["saves","Saves"],["leads","Leads"],["calls_booked","Calls booked"],["calls_attended","Calls attended"],["clients_acquired","Clients acquired"],["revenue","Revenue"]].map(([k,n])=>`<label>${n}<input type="number" min="0" step="any" name="${k}"></label>`).join("")}</div><button class="btn">Save report</button><div data-message class="notice" hidden></div></form></section><section class="section"><h2>Historical reports</h2><div id="metrics" class="card"><div class="empty">Loading…</div></div></section><script>protect().then(async()=>{const [c,d]=await Promise.all([req('/clients'),req('/performance')]);document.getElementById('metricClient').innerHTML=(c.data||[]).map(x=>'<option value="'+safe(x.id)+'">'+safe(x.business_name)+'</option>').join('');renderMetrics(d.data||[])}).catch(showError);function renderMetrics(a){document.getElementById('metrics').innerHTML=a.length?'<div class="grid">'+[["Latest followers",a.find(x=>x.followers!=null)?.followers??'—'],["Leads reported",a.reduce((n,x)=>n+(x.leads||0),0)],["Calls booked",a.reduce((n,x)=>n+(x.calls_booked||0),0)],["Clients acquired",a.reduce((n,x)=>n+(x.clients_acquired||0),0)]].map(x=>'<div class="card"><span class="muted">'+x[0]+'</span><div class="metric">'+safe(x[1])+'</div></div>').join('')+'</div><table class="table section"><thead><tr><th>Date</th><th>Client</th><th>Followers</th><th>Views</th><th>Reach</th><th>Leads</th><th>Calls</th><th>Acquired</th><th>Source</th></tr></thead><tbody>'+a.map(x=>'<tr><td>'+safe(x.recorded_at)+'</td><td>'+safe(x.clients?.business_name||'Client')+'</td><td>'+safe(x.followers??'—')+'</td><td>'+safe(x.views??'—')+'</td><td>'+safe(x.reach??'—')+'</td><td>'+safe(x.leads??'—')+'</td><td>'+safe(x.calls_booked??'—')+'</td><td>'+safe(x.clients_acquired??'—')+'</td><td>'+safe(x.source)+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No performance reports yet. Add the first manual record above.</div>'}document.getElementById('metricForm').addEventListener('submit',e=>submitForm(e,fd=>{const v=Object.fromEntries(fd);for(const k of Object.keys(v))if(v[k]==='')v[k]=null;return req('/performance',{method:'POST',body:JSON.stringify(v)}).then(d=>{setTimeout(()=>location.reload(),700);return d})}))</script>`}
function clientPage(path){const section=path.split("/")[2]||"dashboard";const title={dashboard:"Your dashboard",instagram:"My Instagram",references:"My references",upload:"Upload videos",videos:"My videos",calendar:"Content calendar",results:"My results",settings:"Account settings"}[section]||"Your dashboard";let inner="";
 if(section==="dashboard")inner=`<div class="grid" id="stats"></div><div class="columns section"><section class="card"><h2>Next steps</h2><div id="steps" class="empty">Loading your workspace…</div></section><section class="card"><h2>Recent videos</h2><div id="recent" class="empty">Loading…</div></section></div><script>protect().then(async d=>{const [dash,vids,refs]=await Promise.all([req('/dashboard'),req('/videos'),req('/references')]);const c=d.profile.client_id?dash.data?.[0]:null;document.getElementById('stats').innerHTML=[["Instagram followers",c?.current_followers??'—'],["Follower growth",c?.current_followers!=null&&c?.starting_followers!=null?c.current_followers-c.starting_followers:'—'],["Growth since baseline",c?.current_followers!=null&&c?.starting_followers>0?(((c.current_followers-c.starting_followers)/c.starting_followers)*100).toFixed(1)+'%':'—'],["Onboarding",c?.onboarding_status||'Not started'],["Assigned references",refs.data?.length||0],["Videos in progress",(vids.data||[]).filter(x=>!['Published','Approved'].includes(x.status)).length]].map(x=>'<article class="card"><span class="muted">'+x[0]+'</span><div class="metric">'+x[1]+'</div></article>').join('');document.getElementById('steps').innerHTML='<a class="row" href="/portal/onboarding">Complete or continue onboarding <span>→</span></a><a class="row" href="/portal/references">Review assigned references <span>→</span></a><a class="row" href="/portal/upload">Submit a recording <span>→</span></a>';const a=vids.data||[];document.getElementById('recent').innerHTML=a.length?a.slice(0,5).map(x=>'<div class="row"><b>'+x.title+'</b><span class="badge">'+x.status+'</span></div>').join(''):'<div class="empty">No video submissions yet.</div>'}).catch(showError)</script>`;
 if(section==="instagram")inner=`<section class="card"><h2>Your Instagram account</h2><p class="muted">Your account details are used to tailor content strategy. ForceAim never asks for your Instagram password or security codes.</p><div id="instagramDetails" class="notice">Loading account details…</div><a class="btn ghost" href="/portal/onboarding">Review onboarding details</a></section><script>protect().then(()=>req('/dashboard')).then(d=>{const c=d.data?.[0]||{};const name=c.instagram_username?'@'+safe(c.instagram_username):'Not added yet';document.getElementById('instagramDetails').innerHTML='<div class="row"><span>Username</span><b>'+name+'</b></div><div class="row"><span>Profile</span>'+(c.instagram_url?'<a href="'+safeURL(c.instagram_url)+'" target="_blank" rel="noopener">Open profile ↗</a>':'<span class="muted">Not provided</span>')+'</div><div class="row"><span>Current followers</span><b>'+safe(c.current_followers??'Not provided')+'</b></div><div class="row"><span>Starting followers</span><b>'+safe(c.starting_followers??'Not provided')+'</b></div>'}).catch(showError)</script>`; if(section==="references")inner=`<section id="refCards" class="grid"><div class="empty">Loading assigned references…</div></section><script>protect().then(()=>req('/references')).then(d=>{const a=d.data||[];document.getElementById('refCards').innerHTML=a.length?a.map(x=>'<article class="card"><span class="badge">'+safe(x.reference.category)+'</span><h2>'+safe(x.reference.title)+'</h2><p class="muted">'+safe(x.reference.description||'')+'</p><p>'+safe(x.reference.recording_instructions||'')+'</p><div class="muted">'+(x.reference_reviews?.length?'Reviewed':'Not reviewed yet')+'</div><div class="row">'+(x.reference.instagram_url?'<a class="btn ghost" target="_blank" rel="noopener" href="'+safeURL(x.reference.instagram_url)+'">Open Instagram ↗</a>':'')+(x.reference.youtube_url?'<a class="btn ghost" target="_blank" rel="noopener" href="'+safeURL(x.reference.youtube_url)+'">Open YouTube ↗</a>':'')+'</div>'+(x.reference.video_storage_path?'<button class="btn ghost" data-preview="'+safe(x.reference_id)+'">Preview reference video</button>':'')+' <button class="btn ghost" data-reviewed="'+safe(x.reference_id)+'">Mark reviewed</button> <a class="btn" href="/portal/upload?reference='+encodeURIComponent(x.reference_id)+'">Record and upload</a><video controls hidden style="width:100%;margin-top:12px" id="preview-'+safe(x.reference_id)+'"></video></article>').join(''):'<div class="empty">No published references have been assigned to you yet.</div>';document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=async()=>{try{const u=await req('/reference-url?id='+encodeURIComponent(b.dataset.preview));const v=document.getElementById('preview-'+b.dataset.preview);v.src=u.url;v.hidden=false;await v.play()}catch(e){alert(e.message)}});document.querySelectorAll('[data-reviewed]').forEach(b=>b.onclick=async()=>{try{const d=await req('/reference-review',{method:'POST',body:JSON.stringify({reference_id:b.dataset.reviewed})});b.textContent=d.message}catch(e){alert(e.message)}})}).catch(showError)</script>`;
 if(section==="upload")inner=`<section class="card"><h2>Submit raw footage</h2><p class="muted">Upload MP4 or MOV. Your original footage stays private and separate from edited versions.</p><form id="uploadForm" class="form"><label>Video title<input name="title" required></label><label>Description<textarea name="description"></textarea></label><label>Recording notes<textarea name="recording_notes"></textarea></label><label>Reference<select name="reference_id" id="refs"><option value="">No reference</option></select></label><label>Video file<input type="file" name="file" accept="video/mp4,video/quicktime,.mp4,.mov" required></label><progress id="progress" max="100" value="0" style="width:100%"></progress><button class="btn">Upload footage</button><div data-message class="notice" hidden></div></form></section><script>protect().then(async()=>{const q=new URLSearchParams(location.search).get('reference');const d=await req('/references');document.getElementById('refs').innerHTML='<option value="">No reference</option>'+(d.data||[]).map(x=>'<option value="'+x.reference_id+'" '+(x.reference_id===q?'selected':'')+'>'+x.reference.title+'</option>').join('')});document.getElementById('uploadForm').addEventListener('submit',e=>submitForm(e,async fd=>{const f=fd.get('file');const max=${Number(process.env.MAX_VIDEO_SIZE_MB||500)}*1024*1024;if(!f||f.size>max)throw Error('Choose a video under ${Number(process.env.MAX_VIDEO_SIZE_MB||500)} MB.');if(!['video/mp4','video/quicktime'].includes(f.type))throw Error('Only MP4 and MOV video files are supported.');const up=await req('/upload-token',{method:'POST',body:JSON.stringify({filename:f.name,size:f.size,type:f.type})});const progress=document.getElementById('progress');await uploadSigned(up.url,f,n=>progress.value=n);return req('/videos',{method:'POST',body:JSON.stringify({title:fd.get('title'),description:fd.get('description'),recording_notes:fd.get('recording_notes'),reference_id:fd.get('reference_id')||null,storage_path:up.path})})}));</script>`;
 if(section==="videos")inner=`<section id="videoRows" class="calendar"><div class="empty">Loading…</div></section><script>protect().then(()=>req('/videos')).then(d=>{const a=d.data||[];document.getElementById('videoRows').innerHTML=a.length?a.map(v=>'<article class="card"><div class="row"><div><h2>'+safe(v.title)+'</h2><div class="muted">'+safe(v.status)+'</div></div><span class="badge">'+safe(v.status)+'</span></div>'+(v.video_versions||[]).map(x=>'<div class="row"><span>Edited version '+safe(x.version_number)+'</span><button class="btn ghost" data-play="'+safe(x.id)+'">Preview / download</button></div>').join('')+(v.status==='Ready for Review'?'<form class="form review-form" data-review="'+safe(v.id)+'"><label>Revision notes<textarea name="feedback" placeholder="Tell us what should change. Leave blank to approve."></textarea></label><div class="row"><button class="btn" name="action" value="approve">Approve video</button><button class="btn ghost" name="action" value="changes">Request changes</button></div><div data-message class="notice" hidden></div></form>':'')+'</article>').join(''):'<div class="empty">No video submissions yet. <a href="/portal/upload">Upload your first video</a>.</div>';document.querySelectorAll('[data-play]').forEach(b=>b.onclick=async()=>{try{const d=await req('/version-url?id='+encodeURIComponent(b.dataset.play));window.open(d.url,'_blank','noopener')}catch(e){alert(e.message)}});document.querySelectorAll('.review-form').forEach(f=>f.addEventListener('submit',e=>{const action=e.submitter?.value;submitForm(e,fd=>req('/video-feedback',{method:'POST',body:JSON.stringify({video_id:f.dataset.review,feedback:fd.get('feedback'),action})}).then(d=>{setTimeout(()=>location.reload(),800);return {message:action==='approve'?'Video approved.':'Changes requested.'}}))}))}).catch(showError)</script>`;
 if(section==="calendar")inner=clientData("calendar","Your upcoming content");if(section==="notifications")inner=notificationsPage();if(section==="results")inner=clientResultsPage();
 if(section==="settings")inner=`<section class="card"><h2>Account security</h2><p class="muted">Manage your password using the password reset link on the sign-in page. Instagram passwords and security codes are never collected.</p><a href="/login" class="btn ghost" data-logout>Sign out</a></section>`;
 if(section==="onboarding")inner=onboardingPage();
 return layout("client",title,title,"Your content system, recordings, and results in one place.",inner);
}
function notificationsPage(){return `<section id="notificationRows" class="calendar"><div class="empty">Loading notifications…</div></section><script>protect().then(()=>req('/notifications')).then(d=>{const a=d.data||[];document.getElementById('notificationRows').innerHTML=a.length?a.map(n=>'<article class="card"><div class="row"><div><b>'+safe(n.message)+'</b><div class="muted">'+safe(n.event_type)+' · '+safe(new Date(n.created_at).toLocaleString())+'</div></div>'+(!n.read_at?'<button class="btn ghost" data-read="'+safe(n.id)+'">Mark read</button>':'<span class="badge">Read</span>')+'</div></article>').join(''):'<div class="empty">No notifications yet.</div>';document.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{await req('/notification-read',{method:'POST',body:JSON.stringify({id:b.dataset.read})});b.closest('article').remove()})}).catch(showError)</script>`}
function legacyClientResultsPage(){return `<div class="grid" id="resultStats"></div><section class="card section"><div class="top"><div><h2>Follower trend</h2><p class="muted">Manually reported follower counts over time.</p></div><button class="btn ghost" id="exportMetrics">Export CSV</button></div><div id="followerChart" aria-label="Follower history chart"></div></section><section class="card section"><h2>Reported metrics</h2><div id="resultRows" class="empty">Loading…</div></section><script>protect().then(()=>req('/performance')).then(d=>{const a=d.data||[],followers=a.filter(x=>x.followers!=null).slice().reverse();const latest=followers.at(-1)?.followers,first=followers[0]?.followers;const leads=a.reduce((s,x)=>s+(x.leads||0),0),booked=a.reduce((s,x)=>s+(x.calls_booked||0),0),attended=a.reduce((s,x)=>s+(x.calls_attended||0),0),acquired=a.reduce((s,x)=>s+(x.clients_acquired||0),0);const stats=[["Current followers",latest??'—'],["Growth in reports",latest!=null&&first!=null?latest-first:'—'],["Leads reported",leads],["Calls booked",booked],["Attendance rate",booked>0?((attended/booked)*100).toFixed(1)+'%':'—'],["Clients acquired",acquired]];document.getElementById('resultStats').innerHTML=stats.map(x=>'<article class="card"><span class="muted">'+safe(x[0])+'</span><div class="metric">'+safe(x[1])+'</div></article>').join('');if(followers.length>1){const vals=followers.map(x=>x.followers),min=Math.min(...vals),max=Math.max(...vals),span=Math.max(1,max-min),pts=vals.map((v,i)=>(20+i*560/(vals.length-1))+','+(90-(v-min)*75/span)).join(' ');document.getElementById('followerChart').innerHTML='<svg viewBox="0 0 600 110" role="img" aria-label="Follower count trend" style="width:100%;height:auto"><polyline points="'+pts+'" fill="none" stroke="#c4f26a" stroke-width="3"/><line x1="20" y1="92" x2="580" y2="92" stroke="#39413c"/></svg><div class="row"><span>'+safe(followers[0].recorded_at)+'</span><span>'+safe(followers.at(-1).recorded_at)+'</span></div>'}else document.getElementById('followerChart').innerHTML='<div class="empty">Add at least two follower reports to see a trend.</div>';document.getElementById('resultRows').innerHTML=a.length?a.map(x=>'<div class="row"><div><b>'+safe(x.video_title||x.recorded_at)+'</b><div class="muted">'+safe(x.source)+' · '+safe(x.instagram_url||'')+'</div></div><span class="badge">'+safe(x.views??'—')+' views</span></div>').join(''):'<div class="empty">No performance reports have been added yet.</div>';document.getElementById('exportMetrics').onclick=()=>{const keys=['recorded_at','video_title','instagram_url','published_at','followers','views','reach','likes','comments','shares','saves','leads','calls_booked','calls_attended','clients_acquired','revenue','source'];const csv=[keys.join(','),...a.map(x=>keys.map(k=>'"'+String(x[k]??'').replaceAll('"','""')+'"').join(','))].join('\\n'),blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='forceaim-performance.csv';link.click();URL.revokeObjectURL(url)};}).catch(showError)</script>`}
function clientData(endpoint,label){return `<section class="card"><h2>${label}</h2><div id="rows" class="empty">Loading…</div></section><script>protect().then(()=>req('/${endpoint}')).then(d=>{const a=d.data||[];document.getElementById('rows').innerHTML=a.length?a.map(x=>'<div class="row"><div><b>'+safe(x.title||x.recorded_at||x.scheduled_at)+'</b><div class="muted">'+safe(x.status||x.source||'Manual report')+'</div></div><span class="badge">'+safe(x.views??x.followers??'Saved')+'</span></div>').join(''):'<div class="empty">No records yet. Your agency will add updates here.</div>'}).catch(showError)</script>`}
function legacyOnboardingPage(){const fields={basic:[["full_name","Full name"],["business_name","Business name"],["country","Country"],["timezone","Time zone"],["whatsapp","WhatsApp number (optional)"],["preferred_contact","Preferred contact method"]],instagram:[["username","Instagram username"],["profile_url","Profile URL"],["account_type","Account type"],["followers","Current follower count"],["reel_views","Average Reel views"],["notes","Account notes"]],business:[["niche","Coaching niche"],["offer","Main coaching offer"],["ideal_customer","Ideal customer"],["problem","Problem solved"],["result","Result offered"],["price","Coaching price"],["acquisition_methods","Current client acquisition methods"]],baseline:[["starting_followers","Starting follower count"],["average_reel_views","Average Reel views"],["monthly_leads","Monthly leads"],["calls_booked","Calls booked"],["calls_attended","Calls attended"],["clients_acquired","Clients acquired"],["revenue","Monthly revenue (optional)"],["goal","Primary 90-day goal"]],preferences:[["experience","Content experience"],["best_videos","Best-performing video links"],["style","Preferred video style"],["camera_comfort","Comfort on camera"],["availability","Recording availability"],["frequency","Posting frequency"],["brand_colours","Brand colours"],["instructions","Content instructions"]]};return `<section class="card"><div class="eyebrow">CLIENT ONBOARDING</div><h2 id="stepTitle">Basic information</h2><div class="tabs" id="stepTabs">${Object.keys(fields).map((s,i)=>`<button type="button" data-step="${s}" class="${i===0?'active':''}">${i+1}. ${s[0].toUpperCase()+s.slice(1)}</button>`).join("")}</div><form id="onboard" class="form"><div id="stepFields" class="form"></div><div class="row"><button type="button" class="btn ghost" id="prev">Previous</button><button type="submit" class="btn" id="save">Save and continue</button></div><div class="notice" data-message hidden></div></form></section><script>const order=${JSON.stringify(Object.keys(fields))};const labels=${JSON.stringify(fields)};let current='basic',all={},reviewMode=false;function showStep(s){current=s;reviewMode=false;document.getElementById('stepTitle').textContent=s[0].toUpperCase()+s.slice(1);document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',b.dataset.step===s));document.getElementById('stepFields').innerHTML=labels[s].map(([k,n])=>'<label>'+n+(k==='notes'||k==='instructions'||k==='offer'||k==='ideal_customer'||k==='problem'||k==='result'||k==='acquisition_methods'||k==='goal'?'<textarea name="'+k+'">'+(all[s]?.[k]||'')+'</textarea>':'<input name="'+k+'" value="'+(all[s]?.[k]||'')+'">')+'</label>').join('');document.getElementById('prev').disabled=order.indexOf(s)===0;document.getElementById('save').textContent=order.indexOf(s)===order.length-1?'Submit onboarding':'Save and continue'}document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>showStep(b.dataset.step));document.getElementById('prev').onclick=()=>showStep(order[Math.max(0,order.indexOf(current)-1)]);protect().then(()=>req('/onboarding')).then(d=>{for(const x of d.data||[])all[x.step]=x.response||{};showStep('basic')}).catch(showError);document.getElementById('onboard').addEventListener('submit',e=>submitForm(e,async fd=>{if(reviewMode){await req('/onboarding',{method:'POST',body:JSON.stringify({step:'preferences',response:{...all.preferences,submitted:true,submitted_at:new Date().toISOString()}})});return {message:'Onboarding submitted.'}}all[current]=Object.fromEntries(fd);await req('/onboarding',{method:'POST',body:JSON.stringify({step:current,response:all[current]})});const i=order.indexOf(current);if(i<order.length-1){showStep(order[i+1]);return {message:'Progress saved.'}}reviewMode=true;document.getElementById('stepTitle').textContent='Review your answers';document.getElementById('stepFields').innerHTML='<div class="notice">Review the information below. Use a step above to make changes, then return here to submit.</div><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+safe(JSON.stringify(all,null,2))+'</pre>';return {message:'Review your answers, then choose Submit onboarding.'}}))</script>`}
function adminPerformancePage(){return `<section class="card"><h2>Tracked Calendly booking link</h2><p class="muted">Set the client's real booking page. The portal generates a tracked link; each redirect is counted. Confirmed bookings are recorded by Calendly's signed webhook when configured.</p><form id="bookingForm" class="form"><label>Client<select name="client_id" id="bookingClient" required></select></label><label>Calendly destination URL<input name="booking_url" id="bookingUrl" type="url" placeholder="https://calendly.com/your-event"></label><button class="btn">Save booking destination</button><div data-message class="notice" hidden></div></form><div id="trackedLink" class="notice">Choose a client to load the tracked link.</div></section><section class="card section"><h2>Add Instagram and business metrics</h2><p class="muted">Enter figures from Instagram Insights or your sales records. Empty fields stay unknown. Meta views are used for recent content instead of deprecated impressions.</p><form id="metricForm" class="form"><div class="columns"><label>Client<select name="client_id" id="metricClient" required></select></label><label>Report date<input type="date" name="recorded_at" required></label></div><div class="columns"><label>Video title<input name="video_title"></label><label>Instagram Reel URL<input type="url" name="instagram_url"></label><label>Publication date<input type="date" name="published_at"></label></div><div class="grid">${[["followers","Current followers"],["follows","Follows"],["unfollows","Unfollows"],["profile_link_taps","Profile link taps"],["accounts_engaged","Accounts engaged"],["total_interactions","Total interactions"],["views","Views"],["reach","Reach"],["likes","Likes"],["comments","Comments"],["shares","Shares"],["saves","Saves"],["leads","Leads"],["calls_booked","Manually reported calls booked"],["calls_attended","Calls attended"],["clients_acquired","Clients acquired"],["revenue","Revenue"]].map(([k,n])=>`<label>${n}<input type="number" min="0" step="1" name="${k}"></label>`).join("")}</div><button class="btn">Save report</button><div data-message class="notice" hidden></div></form></section><section class="section"><h2>Historical reports and booking funnel</h2><div id="metrics" class="card"><div class="empty">Loading…</div></div></section><script>protect().then(async()=>{const [c,d]=await Promise.all([req('/clients'),req('/performance')]),clients=c.data||[];document.getElementById('metricClient').innerHTML=clients.map(x=>'<option value="'+safe(x.id)+'">'+safe(x.business_name)+'</option>').join('');document.getElementById('bookingClient').innerHTML=clients.map(x=>'<option value="'+safe(x.id)+'">'+safe(x.business_name)+'</option>').join('');renderMetrics(d.data||[],d.booking_stats?.by_client||[]);await loadBookingLink()}).catch(showError);async function loadBookingLink(){const id=document.getElementById('bookingClient').value;if(!id)return;try{const d=await req('/booking-link?client_id='+encodeURIComponent(id));document.getElementById('bookingUrl').value=d.booking_url||'';document.getElementById('trackedLink').innerHTML=d.tracked_url?'Tracked URL: <a href="'+safeURL(d.tracked_url)+'" target="_blank" rel="noopener">'+safe(d.tracked_url)+'</a> <button class="btn ghost" type="button" id="copyTracked">Copy</button>':'Save a Calendly destination to create the tracked link.';document.getElementById('copyTracked')?.addEventListener('click',()=>navigator.clipboard.writeText(d.tracked_url))}catch(e){document.getElementById('trackedLink').textContent=e.message}}document.getElementById('bookingClient').addEventListener('change',loadBookingLink);document.getElementById('bookingForm').addEventListener('submit',e=>submitForm(e,async fd=>{const d=await req('/booking-link',{method:'PUT',body:JSON.stringify(Object.fromEntries(fd))});await loadBookingLink();return {message:'Booking destination saved.'}}));function renderMetrics(a,stats){const funnel=stats.map(x=>'<tr><td>'+safe((document.querySelector('#bookingClient option[value="'+x.client_id+'"]')||{}).textContent||'Client')+'</td><td>'+safe(x.clicks)+'</td><td>'+safe(x.bookings)+'</td></tr>').join('');document.getElementById('metrics').innerHTML=(stats.length?'<h3>Booking funnel counts</h3><table class="table"><thead><tr><th>Client</th><th>Tracked link clicks</th><th>Confirmed active bookings</th></tr></thead><tbody>'+funnel+'</tbody></table>':'<div class="empty">No tracked booking clicks or confirmed bookings yet.</div>')+(a.length?'<table class="table section"><thead><tr><th>Date</th><th>Client</th><th>Followers</th><th>Follows</th><th>Views</th><th>Reach</th><th>Interactions</th><th>Leads</th><th>Manual calls</th><th>Source</th></tr></thead><tbody>'+a.map(x=>'<tr><td>'+safe(x.recorded_at)+'</td><td>'+safe(x.clients?.business_name||'Client')+'</td><td>'+safe(x.followers??'—')+'</td><td>'+safe(x.follows??'—')+'</td><td>'+safe(x.views??'—')+'</td><td>'+safe(x.reach??'—')+'</td><td>'+safe(x.total_interactions??'—')+'</td><td>'+safe(x.leads??'—')+'</td><td>'+safe(x.calls_booked??'—')+'</td><td>'+safe(x.source)+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No performance reports yet.</div>')}}document.getElementById('metricForm').addEventListener('submit',e=>submitForm(e,fd=>{const v=Object.fromEntries(fd);for(const k of Object.keys(v))if(v[k]==='')v[k]=null;return req('/performance',{method:'POST',body:JSON.stringify(v)}).then(d=>{setTimeout(()=>location.reload(),700);return d})}))</script>`}

function clientResultsPage(){return `<div class="grid" id="resultStats"></div><section class="card section"><div class="top"><div><h2>Follower trend</h2><p class="muted">Historical follower snapshots; missing reports are not treated as zero.</p></div><button class="btn ghost" id="exportMetrics">Export CSV</button></div><div id="followerChart" aria-label="Follower history chart"></div></section><section class="card section"><h2>Tracked booking link</h2><p class="muted">Use this link in your Instagram bio or content CTA so ForceAim can count visits and match confirmed Calendly bookings.</p><div id="clientBookingLink" class="notice">Loading your tracked link…</div></section><section class="card section"><h2>Instagram and business reports</h2><div id="resultRows" class="empty">Loading…</div></section><script>protect().then(async()=>{const [d,l]=await Promise.all([req('/performance'),req('/booking-link')]),a=d.data||[],stats=d.booking_stats||{clicks:0,bookings:0},followers=a.filter(x=>x.followers!=null).slice().reverse(),latest=followers.at(-1)?.followers,first=followers[0]?.followers;const manualCalls=a.reduce((s,x)=>s+(x.calls_booked||0),0),leads=a.reduce((s,x)=>s+(x.leads||0),0),attended=a.reduce((s,x)=>s+(x.calls_attended||0),0),acquired=a.reduce((s,x)=>s+(x.clients_acquired||0),0);const cards=[["Current followers",latest??'—'],["Follower growth",latest!=null&&first!=null?latest-first:'—'],["Tracked booking link clicks",stats.clicks],["Confirmed Calendly bookings",stats.bookings],["Manually reported calls booked",manualCalls],["Leads reported",leads],["Calls attended",attended],["Clients acquired",acquired]];document.getElementById('resultStats').innerHTML=cards.map(x=>'<article class="card"><span class="muted">'+safe(x[0])+'</span><div class="metric">'+safe(x[1])+'</div></article>').join('');document.getElementById('clientBookingLink').innerHTML=l.tracked_url?'<a href="'+safeURL(l.tracked_url)+'" target="_blank" rel="noopener">'+safe(l.tracked_url)+'</a> <button class="btn ghost" id="copyLink">Copy link</button>':'The agency has not configured a booking destination yet.';document.getElementById('copyLink')?.addEventListener('click',()=>navigator.clipboard.writeText(l.tracked_url));if(followers.length>1){const vals=followers.map(x=>x.followers),min=Math.min(...vals),max=Math.max(...vals),span=Math.max(1,max-min),pts=vals.map((v,i)=>(20+i*560/(vals.length-1))+','+(90-(v-min)*75/span)).join(' ');document.getElementById('followerChart').innerHTML='<svg viewBox="0 0 600 110" role="img" aria-label="Follower count trend" style="width:100%;height:auto"><polyline points="'+pts+'" fill="none" stroke="#c4f26a" stroke-width="3"/><line x1="20" y1="92" x2="580" y2="92" stroke="#39413c"/></svg><div class="row"><span>'+safe(followers[0].recorded_at)+'</span><span>'+safe(followers.at(-1).recorded_at)+'</span></div>'}else document.getElementById('followerChart').innerHTML='<div class="empty">Add at least two follower reports to see a trend.</div>';document.getElementById('resultRows').innerHTML=a.length?a.map(x=>'<article class="card section"><div class="row"><b>'+safe(x.video_title||x.recorded_at)+'</b><span class="badge">'+safe(x.source==='meta'?'Instagram API':'Manual report')+'</span></div><div class="grid">'+[["Followers",x.followers],["Follows",x.follows],["Unfollows",x.unfollows],["Views",x.views],["Reach",x.reach],["Likes",x.likes],["Comments",x.comments],["Shares",x.shares],["Saves",x.saves],["Accounts engaged",x.accounts_engaged],["Total interactions",x.total_interactions],["Profile link taps",x.profile_link_taps],["Leads",x.leads],["Calls booked",x.calls_booked],["Calls attended",x.calls_attended]].filter(y=>y[1]!=null).map(y=>'<div class="card"><span class="muted">'+safe(y[0])+'</span><div class="metric">'+safe(y[1])+'</div></div>').join('')+'</div><div class="muted">'+safe(x.instagram_url||'')+'</div></article>').join(''):'<div class="empty">No performance reports have been added yet.</div>';document.getElementById('exportMetrics').onclick=()=>{const keys=['recorded_at','video_title','instagram_url','published_at','followers','follows','unfollows','profile_link_taps','accounts_engaged','total_interactions','views','reach','likes','comments','shares','saves','leads','calls_booked','calls_attended','clients_acquired','revenue','source'];const csv=[keys.join(','),...a.map(x=>keys.map(k=>'"'+String(x[k]??'').replaceAll('"','""')+'"').join(','))].join('\\n'),blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='forceaim-performance.csv';link.click();URL.revokeObjectURL(url)}}).catch(showError)</script>`}

function onboardingPage(){
 const fields={basic:[["full_name","Full name"],["business_name","Business name"],["country","Country"],["timezone","Time zone"],["whatsapp","WhatsApp number (optional)"],["preferred_contact","Preferred contact method"]],instagram:[["username","Instagram username"],["profile_url","Profile URL"],["account_type","Account type"],["followers","Current follower count"],["reel_views","Average Reel views"],["notes","Account notes"]],business:[["niche","Coaching niche"],["offer","Main coaching offer"],["ideal_customer","Ideal customer"],["problem","Problem solved"],["result","Result offered"],["price","Coaching price"],["acquisition_methods","Current client acquisition methods"]],baseline:[["starting_followers","Starting follower count"],["average_reel_views","Average Reel views"],["monthly_leads","Monthly leads"],["calls_booked","Calls booked"],["calls_attended","Calls attended"],["clients_acquired","Clients acquired"],["revenue","Monthly revenue (optional)"],["goal","Primary 90-day goal"]],preferences:[["experience","Content experience"],["best_videos","Best-performing video links"],["style","Preferred video style"],["camera_comfort","Comfort on camera"],["availability","Recording availability"],["frequency","Posting frequency"],["brand_colours","Brand colours"],["instructions","Content instructions"]]};
 return `<section class="card"><div class="eyebrow">CLIENT ONBOARDING</div><h2 id="stepTitle">Basic information</h2><p class="muted" id="stepHelp">Your answers save as you move through the steps. You can leave and resume later.</p><div class="tabs" id="stepTabs">${Object.keys(fields).map((s,i)=>`<button type="button" data-step="${s}" class="${i===0?'active':''}">${i+1}. ${s[0].toUpperCase()+s.slice(1)}</button>`).join("")}</div><form id="onboard" class="form" novalidate><div id="stepFields" class="form"></div><div class="row"><button type="button" class="btn ghost" id="prev">Previous</button><button type="submit" class="btn" id="save">Save and continue</button></div><div class="notice" data-message hidden aria-live="polite"></div></form></section><script>
const order=${JSON.stringify(Object.keys(fields))},labels=${JSON.stringify(fields)};let current='basic',all={},reviewMode=false,finished=false,ready=false;
const onboard=document.getElementById('onboard'),saveButton=document.getElementById('save'),message=onboard.querySelector('[data-message]');
function showStep(s){current=s;reviewMode=false;document.getElementById('stepTitle').textContent=s[0].toUpperCase()+s.slice(1);document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',b.dataset.step===s));document.getElementById('stepFields').innerHTML=labels[s].map(([k,n])=>{const value=safe(all[s]?.[k]||'');const big=['notes','instructions','offer','ideal_customer','problem','result','acquisition_methods','goal','niche','style','camera_comfort','availability','experience','best_videos'].includes(k);const type=['followers','reel_views','starting_followers','average_reel_views','monthly_leads','calls_booked','calls_attended','clients_acquired','revenue'].includes(k)?'number':k==='profile_url'?'url':'text';const required=s==='basic'&&['full_name','business_name'].includes(k)?' required':'';const attrs=type==='number'?' min="0" step="1"':'';return '<label>'+safe(n)+(big?'<textarea name="'+safe(k)+'"'+required+'>'+value+'</textarea>':'<input name="'+safe(k)+'" type="'+type+'"'+attrs+required+' value="'+value+'">')+'</label>'}).join('');document.getElementById('prev').disabled=order.indexOf(s)===0;saveButton.textContent=order.indexOf(s)===order.length-1?'Review answers':'Save and continue';}
function capture(){if(!reviewMode&&current)all[current]=Object.fromEntries(new FormData(onboard))}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{capture();showStep(b.dataset.step)});document.getElementById('prev').onclick=()=>{capture();showStep(order[Math.max(0,order.indexOf(current)-1)]);window.scrollTo({top:0,behavior:'smooth'})};
const loadOnboarding=protect().then(()=>req('/onboarding')).then(d=>{for(const x of d.data||[])all[x.step]=x.response||{};ready=true;showStep('basic')}).catch(e=>{ready=false;showError(e)});
onboard.addEventListener('submit',async e=>{e.preventDefault();if(saveButton.disabled||finished)return;capture();if(!reviewMode&&current==='basic'&&(!String(all.basic.full_name||'').trim()||!String(all.basic.business_name||'').trim())){message.hidden=false;message.className='notice error';message.textContent='Please enter your full name and business name before continuing.';const missing=!String(all.basic.full_name||'').trim()?'full_name':'business_name';onboard.querySelector('[name="'+missing+'"]')?.focus();return}saveButton.disabled=true;const oldText=saveButton.textContent;saveButton.textContent='Saving…';message.hidden=true;try{await loadOnboarding;if(!ready)throw Error('Your workspace could not be loaded. Refresh the page and sign in again.');if(reviewMode){await req('/onboarding',{method:'POST',body:JSON.stringify({step:'preferences',response:{...all.preferences,submitted:true,submitted_at:new Date().toISOString()}})});finished=true;document.getElementById('stepTitle').textContent='Onboarding complete';document.getElementById('stepFields').innerHTML='<div class="notice">Thanks. Your answers were submitted successfully. The agency can now prepare your content plan.</div><a class="btn" href="/portal">Go to dashboard</a>';document.getElementById('stepTabs').hidden=true;message.hidden=false;message.className='notice';message.textContent='Onboarding submitted.';saveButton.hidden=true;document.getElementById('prev').hidden=true;return}await req('/onboarding',{method:'POST',body:JSON.stringify({step:current,response:all[current]})});const index=order.indexOf(current);message.hidden=false;message.className='notice';message.textContent='Saved. Continuing…';if(index<order.length-1){showStep(order[index+1]);window.scrollTo({top:0,behavior:'smooth'});return}reviewMode=true;document.getElementById('stepTitle').textContent='Review your answers';document.getElementById('stepHelp').textContent='Check your responses below. Choose a step above to make changes.';document.getElementById('stepFields').innerHTML=order.map(step=>'<section class="card"><h3>'+safe(step[0].toUpperCase()+step.slice(1))+'</h3><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+safe(JSON.stringify(all[step]||{},null,2))+'</pre></section>').join('');saveButton.textContent='Submit onboarding';message.textContent='Your answers are saved. Submit when you are ready.';window.scrollTo({top:0,behavior:'smooth'})}catch(err){message.hidden=false;message.className='notice error';message.textContent=err.message||'Could not save. Please try again.';message.scrollIntoView({behavior:'smooth',block:'center'})}finally{if(!finished){saveButton.disabled=false;if(saveButton.textContent==='Saving…')saveButton.textContent=oldText}}});
</script>`;
}

function showError(e){console.error(e);const target=document.querySelector('.content')||document.body;const n=document.createElement('div');n.className='notice error';n.textContent=e.message;target.prepend(n)}
